const SLACK_WEBHOOK = '';
const ctx = $input.first().json.ctx;
const w = ctx.week, c = ctx.coverage;
const n = (x) => Number(x) || 0;
const s = (k) => (k === 1 ? '' : 's');
const agreed = Math.max(0, n(w.total) - n(w.incorrect) - n(w.relabel));
const lines = [':brain: *tnAI learning · weekly digest*'];
if (n(w.total) === 0) {
  lines.push('No feedback given this week - the loop only learns when the team clicks.');
} else {
  lines.push('This week: *' + n(w.total) + ' review' + s(n(w.total)) + '* from ' + n(w.reviewers) + ' reviewer' + s(n(w.reviewers)) + ' - ' + n(w.incorrect) + ' said incorrect, ' + n(w.relabel) + ' relabelled, ' + agreed + ' agreed. ' + n(w.with_reason) + ' of the ' + n(w.total) + ' came with a reason.');
  const tops = (ctx.top_accounts || []).map((a) => a.name + ' (' + a.n + ')').join(', ');
  if (tops) lines.push(':memo: Most reviewed: ' + tops);
  if (n(w.with_reason) * 2 < n(w.total)) lines.push(':bulb: Only ' + n(w.with_reason) + ' of ' + n(w.total) + ' carried a reason - one tapped chip teaches more than ten bare clicks.');
}
lines.push('The classifier carries ' + n(ctx.lessons) + ' lesson' + s(n(ctx.lessons)) + '. ' + n(c.reviewed) + ' of ' + n(c.total) + ' signals have been reviewed so far.');
return [{ json: { webhook: SLACK_WEBHOOK, line: lines.join('\n') } }];
